// averageSpeed.ts
// Export function averageSpeed(distanceKm: number, hours: number): number
// Export function isPositiveNumber(x: unknown): boolean

export function averageSpeed(distanceKm: number, hours: number): number {
    // distance / hours, rounded to 2 decimals
    const result = distanceKm / hours;
    return Math.round(result * 100) / 100;
}

export function isPositiveNumber(x: unknown): boolean {
    if (typeof x !== 'number') return false;
    return x > 0;
}

// Small self-test when run directly (e.g., node averageSpeed.ts)
if (import.meta.main && import.meta.main === 'file') {
    // Run simple assertions
    console.log('Testing averageSpeed...');
    // Example: 240 km over 5 hours => 48 km/h
    const speed = averageSpeed(240, 5);
    console.assert(speed === 48, `Expected 48, got ${speed}`);
    // Test rounding: 1 km over 3 hours = 0.333333... => 0.33
    const speed2 = averageSpeed(1, 3);
    console.assert(speed2 === 0.33, `Expected 0.33, got ${speed2}`);
    // Test isPositiveNumber
    console.assert(isPositiveNumber(5) === true);
    console.assert(isPositiveNumber(0) === false);
    console.assert(isPositiveNumber(-1) === false);
    console.assert(isPositiveNumber('5') === false);
    console.log('All self-tests passed.');
}

